@charset "UTF-8";
/* ===== Priority PR Feed – Modern Enterprise Slate Theme ===== */
/* ── Feed Container ── */
.pr-feed-list {
  display: flex;
  flex-direction: column;
  gap: 12px;
  padding: 16px;
  overflow-y: auto;
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
  background-color: #fff; /* Clean off-white background */
  min-height: 100%;
  box-sizing: border-box;
}

/* Custom Scrollbar for list container */
.pr-feed-list::-webkit-scrollbar {
  width: 6px;
}

.pr-feed-list::-webkit-scrollbar-track {
  background: transparent;
}

.pr-feed-list::-webkit-scrollbar-thumb {
  background: rgba(148, 163, 184, 0.3);
  border-radius: 3px;
}

.pr-feed-list::-webkit-scrollbar-thumb:hover {
  background: rgba(148, 163, 184, 0.5);
}

/* ── Individual Card ── */
.pr-feed-card {
  background: #ffffff;
  border: 1px solid #e2e8f0;
  border-left: 4px solid #ef4444; /* Urgent red accent */
  border-radius: 8px;
  padding: 16px;
  box-shadow: 0 1px 3px 0 rgba(0, 0, 0, 0.05), 0 1px 2px 0 rgba(0, 0, 0, 0.03);
  transition: all 0.25s cubic-bezier(0.4, 0, 0.2, 1);
  display: flex;
  flex-direction: column;
  gap: 10px;
  position: relative;
  cursor: pointer;
}

.pr-feed-card:hover {
  transform: translateY(-2px);
  box-shadow: 0 10px 15px -3px rgba(0, 0, 0, 0.05), 0 4px 6px -2px rgba(0, 0, 0, 0.03);
  border-left-color: #dc2626;
  border-color: #cbd5e1;
}

/* ── Header Row ── */
.pr-feed-card-header {
  display: flex;
  justify-content: space-between;
  align-items: flex-start;
  flex-wrap: wrap;
  gap: 8px;
}

/* PR info wrapper */
.pr-feed-pr-info {
  display: flex;
  align-items: center;
  flex-wrap: wrap;
  gap: 8px;
  min-width: 0;
  flex: 1 1 auto;
}

/* PR Number – Primary highlight */
.pr-feed-pr-number {
  font-size: 15px;
  font-weight: 700;
  color: #0f172a; /* Slate 900 */
  letter-spacing: -0.2px;
}

/* Copy Button */
.pr-feed-copy-btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  background: transparent;
  border: none;
  padding: 4px;
  border-radius: 4px;
  color: #94a3b8; /* Subtle gray */
  cursor: pointer;
  opacity: 0; /* Hidden by default for cleaner UI */
  transition: all 0.2s ease;
}

.pr-feed-card:hover .pr-feed-copy-btn {
  opacity: 1; /* Show on card hover */
}

.pr-feed-copy-btn:hover {
  background-color: #f1f5f9;
  color: #475569;
}

.pr-feed-copy-btn:active {
  transform: scale(0.9);
}

/* Line item count pill */
.pr-feed-item-count {
  font-size: 10px;
  font-weight: 600;
  color: #475569;
  background-color: #f1f5f9;
  border: 1px solid #e2e8f0;
  padding: 2px 6px;
  border-radius: 12px;
  text-transform: lowercase;
  white-space: nowrap;
}

/* Status Badge */
.pr-feed-status-badge {
  display: inline-flex;
  align-items: center;
  padding: 3px 8px;
  border-radius: 4px;
  font-size: 10px;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.4px;
  background-color: #fee2e2;
  color: #991b1b;
  border: 1px solid #fecaca;
  line-height: 1.3;
  flex-shrink: 0;
  max-width: 100%;
  text-align: right;
  word-break: break-word;
}

/* ── Description Container ── */
.pr-feed-description-container {
  margin-top: 2px;
}

/* Description Text – Clamped by default, expands on hover */
.pr-feed-description {
  margin: 0;
  font-size: 13px;
  font-weight: 400;
  color: #475569; /* Slate 600 */
  line-height: 1.5;
  word-break: break-word;
  white-space: pre-wrap;
  display: -webkit-box;
  -webkit-line-clamp: 2;
  line-clamp: 2;
  -webkit-box-orient: vertical;
  overflow: hidden;
  text-overflow: ellipsis;
  max-height: 3em; /* 2 lines */
  transition: max-height 0.3s ease;
}

/* Expand description on card hover */
.pr-feed-card:hover .pr-feed-description {
  display: block;
  overflow: visible;
  -webkit-line-clamp: unset;
  line-clamp: none;
  max-height: none;
}

/* ── Card Footer ── */
.pr-feed-card-footer {
  display: flex;
  justify-content: flex-start;
  margin-top: 4px;
  border-top: 1px dashed #f1f5f9;
  padding-top: 8px;
}

/* Age badge */
.pr-feed-age-badge {
  display: inline-flex;
  align-items: center;
  font-size: 11px;
  font-weight: 600;
  padding: 2px 8px;
  border-radius: 4px;
}

/* Age state: Normal (< 5 days) */
.pr-feed-age-badge.age-normal {
  background-color: #f1f5f9;
  color: #475569;
  border: 1px solid #e2e8f0;
}

/* Age state: Critical (> 5 days) */
.pr-feed-age-badge.age-critical {
  background-color: #fffbeb; /* Light amber */
  color: #d97706; /* Amber 600 */
  border: 1px solid #fef3c7;
}

/* ── Empty State ── */
.pr-feed-empty {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  padding: 48px 24px;
  text-align: center;
  min-height: 100%;
  box-sizing: border-box;
  background-color: #f8fafc;
}

.pr-feed-empty-icon {
  margin-bottom: 16px;
  opacity: 0.8;
}

.pr-feed-empty-title {
  margin: 0 0 6px 0;
  font-size: 16px;
  font-weight: 700;
  color: #1e293b;
}

.pr-feed-empty-sub {
  margin: 0;
  font-size: 13px;
  color: #64748b;
  max-width: 260px;
  line-height: 1.5;
}

